
-- Handbook v1.14 remediation: replace numbered archive placeholders with distinct knowledge records.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'English textincorrect questionsEnglish text' WHEN 1 THEN 'English text' WHEN 2 THEN 'countEnglish textchartsEnglish text'
      WHEN 3 THEN 'clientprogramEnglish text' WHEN 4 THEN 'English text' WHEN 5 THEN 'MBA programEnglish textmaterials'
      WHEN 6 THEN 'English textrecord' WHEN 7 THEN 'English textpleaseEnglish text' WHEN 8 THEN 'officialscore sendingdescription'
      WHEN 9 THEN 'mock examEnglish textcheck' WHEN 10 THEN 'timeEnglish text' WHEN 11 THEN 'English textandEnglish text'
      WHEN 12 THEN 'budgetEnglish textrules' WHEN 13 THEN 'courseEnglish text' WHEN 14 THEN 'English textsessionEnglish text'
      WHEN 15 THEN 'English textriskchecklist' ELSE 'workstudyEnglish text' END AS archive_topic,
    CASE rowid % 19
      WHEN 0 THEN 'alreadyEnglish text' WHEN 1 THEN 'English textsource' WHEN 2 THEN 'English texthistoricalEnglish text' WHEN 3 THEN 'English textandEnglish textnewEnglish text'
      WHEN 4 THEN 'English textaEnglish text' WHEN 5 THEN 'alreadyEnglish textdayEnglish text' WHEN 6 THEN 'alreadyEnglish textbudget' WHEN 7 THEN 'pendingEnglish text'
      WHEN 8 THEN 'noneexternal sharingEnglish text' WHEN 9 THEN 'English text' WHEN 10 THEN 'alreadyEnglish textoldversion' WHEN 11 THEN 'retainEnglish text'
      WHEN 12 THEN 'needEnglish texttimeEnglish text' WHEN 13 THEN 'alreadyEnglish textlowEnglish textfirstEnglish text' WHEN 14 THEN 'availableonEnglish text'
      WHEN 15 THEN 'notEnglish textasofficialEnglish text' WHEN 16 THEN 'alreadyEnglish text' WHEN 17 THEN 'alreadyrecordEnglish textitemEnglish text'
      ELSE 'English textconfirmedafterEnglish text' END AS archive_status
  FROM pages WHERE page_id LIKE 'page_background_examprep_%'
)
UPDATE pages
SET title = CASE rowid % 5
      WHEN 0 THEN (SELECT archive_topic || 'English text｜' || archive_status FROM facts WHERE facts.rid=pages.rowid)
      WHEN 1 THEN (SELECT archive_status || '：' || archive_topic || 'English text' FROM facts WHERE facts.rid=pages.rowid)
      WHEN 2 THEN (SELECT archive_topic || 'ofEnglish textrecord（' || archive_status || '）' FROM facts WHERE facts.rid=pages.rowid)
      WHEN 3 THEN (SELECT 'materialsEnglish text：' || archive_topic || '；status=' || archive_status FROM facts WHERE facts.rid=pages.rowid)
      ELSE (SELECT archive_topic || 'English text，' || archive_status FROM facts WHERE facts.rid=pages.rowid)
    END,
    properties_json = json_object('record_kind','historical_context','topic',(SELECT archive_topic FROM facts WHERE facts.rid=pages.rowid),'status',(SELECT archive_status FROM facts WHERE facts.rid=pages.rowid)),
    page_id = replace(page_id, 'page_background_examprep_', 'page_context_archive_')
WHERE page_id LIKE 'page_background_examprep_%';
